import pty, os, sys, time, select

def run_pty(args, env_extra=None, timeout=5, input_data=b"q"):
    e=dict(os.environ); e["HOME"]="/tmp/fakehome"; e.pop("XDG_CONFIG_HOME",None); e.pop("TAILSPIN_PAGER",None)
    if env_extra: e.update(env_extra)
    pid, fd = pty.fork()
    if pid==0:
        os.execve("./executable", ["./executable"]+args, e)
    out=b""
    start=time.time()
    sent=False
    while time.time()-start<timeout:
        r,_,_=select.select([fd],[],[],0.2)
        if r:
            try:
                data=os.read(fd, 4096)
            except OSError:
                break
            if not data: break
            out+=data
            if not sent:
                # wait a bit then send q
                time.sleep(0.3)
                try: os.write(fd, input_data)
                except: pass
                sent=True
        # check child
        wpid,status=os.waitpid(pid, os.WNOHANG)
        if wpid==pid:
            # drain
            try:
                while True:
                    data=os.read(fd,4096)
                    if not data: break
                    out+=data
            except: pass
            print("exit status", os.waitstatus_to_exitcode(status))
            break
    else:
        print("timeout, killing")
