import subprocess, os, time, select, sys
def env():
    e=dict(os.environ); e["HOME"]="/tmp/fakehome"; e.pop("XDG_CONFIG_HOME",None); e.pop("TAILSPIN_PAGER",None); return e
def avail_fd(fd):
    out=b""
    while True:
        r,_,_=select.select([fd],[],[],0.2)
        if not r: break
        try: c=os.read(fd,4096)
        except: break
        if not c: break
        out+=c
    return out

def run_seq(chunks, label):
    print("===",label,"===")
    proc=subprocess.Popen(["./executable","-p"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env())
    for ch in chunks:
        print(" write", repr(ch))
        if proc.poll() is not None:
            print("  already exited", proc.poll()); break
        try:
            proc.stdin.write(ch); proc.stdin.flush()
        except BrokenPipeError as e:
            print("  broken pipe"); break
        time.sleep(0.4)
        print("  stdout:", repr(avail_fd(proc.stdout.fileno())), "stderr:", repr(avail_fd(proc.stderr.fileno())), "poll", proc.poll())
    if proc.poll() is None:
        try: proc.stdin.close()
        except: pass
        time.sleep(0.4)
        print(" after close stdout:", repr(avail_fd(proc.stdout.fileno())), "stderr:", repr(avail_fd(proc.stderr.fileno())), "poll", proc.poll())
    if proc.poll() is None:
        proc.terminate()
    # drain manually
    time.sleep(0.2)
    print(" final stdout:", repr(avail_fd(proc.stdout.fileno())), "stderr:", repr(avail_fd(proc.stderr.fileno())), "poll", proc.poll())
    try: proc.wait(timeout=2)
    except: proc.kill()
    print(" exit", proc.returncode)

