import subprocess, os, time, signal
def env(extra=None):
    e=dict(os.environ); e["HOME"]="/tmp/fakehome"; e.pop("XDG_CONFIG_HOME",None); e.pop("TAILSPIN_PAGER",None)
    if extra: e.update(extra)
    return e
# Signal tests in -p stdin streaming mode
for sig,name in [(signal.SIGINT,"SIGINT"),(signal.SIGTERM,"SIGTERM"),(signal.SIGPIPE,"SIGPIPE")]:
    proc=subprocess.Popen(["./executable","-p"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env())
    proc.stdin.write(b"hi 123\n"); proc.stdin.flush(); time.sleep(0.3)
    proc.send_signal(sig)
    try: out,err=proc.communicate(timeout=2)
    except: proc.kill(); out,err=proc.communicate()
    print("stdin print",name,proc.returncode,repr(out),repr(err))
# Broken pipe: stdout closed reader
proc=subprocess.Popen(["./executable","-p"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env())
proc.stdout.close()
proc.stdin.write(b"hello 123\n"*1000); 
try:
    proc.stdin.close()
except BrokenPipeError: print("writer broken")
try: proc.wait(timeout=3)
except: proc.kill()
print("brokenpipe stdout stdin mode",proc.returncode, repr(proc.stderr.read() if proc.stderr else b""))
# Use shell: generate example file and pipe to head
p1=subprocess.run("cat example-logs/example5 | ./executable -p | head -n 1; echo PIPESTATUS:${PIPESTATUS[*]}", shell=True, capture_output=True, env=env(), executable="/bin/bash")
print("head pipe",p1.stdout,p1.stderr)
# File print to closed stdout
p1=subprocess.run("./executable -p example-logs/example5 | head -n 1; echo PIPESTATUS:${PIPESTATUS[*]}", shell=True, capture_output=True, env=env(), executable="/bin/bash")
print("head file print",p1.stdout,p1.stderr)
PY"}

