import subprocess, os, string
def env():
    e=dict(os.environ); e["HOME"]="/tmp/fakehome"; e.pop("XDG_CONFIG_HOME",None); e.pop("TAILSPIN_PAGER",None); return e
def run(s):
    return subprocess.run(["./executable","-p","--enable","urls"], input=(s+"\n").encode(), capture_output=True, env=env()).stdout.decode()
allowed=[]; notallowed=[]
for ch in string.printable[:94]:
    if ch=='"': continue
    s=f"https://a.com/b{ch}c"
    out=run(s)
    # path styled segment is \x1b[34m/path... if bc includes ch in styled chunk, the styled chunk will contain b{ch}c
    styled_path=f"\x1b[34m/b{ch}c\x1b[0m" in out
    (allowed if styled_path else notallowed).append(ch)
print("allowed path segment chars:", ''.join(allowed))
print("not:", ''.join(notallowed))
# query key/value char classifier
allowedk=[]; notk=[]
for ch in string.printable[:94]:
    s=f"https://a.com/?a{ch}b=val"
    out=run(s)
    if f"\x1b[35ma{ch}b\x1b[0m" in out: allowedk.append(ch)
    else: notk.append(ch)
print("key allowed",''.join(allowedk)); print("key not",''.join(notk))
allowedv=[]; notv=[]
for ch in string.printable[:94]:
    s=f"https://a.com/?k=a{ch}b"
    out=run(s)
    if f"\x1b[36ma{ch}b\x1b[0m" in out: allowedv.append(ch)
    else: notv.append(ch)
print("value allowed",''.join(allowedv)); print("value not",''.join(notv))
PY"}

