use serde::Deserialize;

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Color {
    Default,
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
    White,
    BrightBlack,
    BrightRed,
    BrightGreen,
    BrightYellow,
    BrightBlue,
    BrightMagenta,
    BrightCyan,
    BrightWhite,
}

impl Color {
    pub fn fg_code(self) -> u8 {
        match self {
            Color::Default => 39,
            Color::Black => 30,
            Color::Red => 31,
            Color::Green => 32,
            Color::Yellow => 33,
            Color::Blue => 34,
            Color::Magenta => 35,
            Color::Cyan => 36,
            Color::White => 37,
            Color::BrightBlack => 90,
            Color::BrightRed => 91,
            Color::BrightGreen => 92,
            Color::BrightYellow => 93,
            Color::BrightBlue => 94,
            Color::BrightMagenta => 95,
            Color::BrightCyan => 96,
            Color::BrightWhite => 97,
        }
    }
    pub fn bg_code(self) -> u8 {
        match self {
            Color::Default => 49,
            Color::Black => 40,
            Color::Red => 41,
            Color::Green => 42,
            Color::Yellow => 43,
            Color::Blue => 44,
            Color::Magenta => 45,
            Color::Cyan => 46,
            Color::White => 47,
            Color::BrightBlack => 100,
            Color::BrightRed => 101,
            Color::BrightGreen => 102,
            Color::BrightYellow => 103,
            Color::BrightBlue => 104,
            Color::BrightMagenta => 105,
            Color::BrightCyan => 106,
            Color::BrightWhite => 107,
        }
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Deserialize)]
#[serde(default)]
pub struct Style {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub bold: bool,
    pub faint: bool,
    pub italic: bool,
    pub underline: bool,
}

impl Style {
    pub const fn new() -> Self {
        Style { fg: None, bg: None, bold: false, faint: false, italic: false, underline: false }
    }
    pub const fn fg(color: Color) -> Self {
        Style { fg: Some(color), bg: None, bold: false, faint: false, italic: false, underline: false }
    }
    pub const fn fg_faint(color: Color) -> Self {
        Style { fg: Some(color), bg: None, bold: false, faint: true, italic: false, underline: false }
    }
    pub const fn faint() -> Self {
        Style { fg: None, bg: None, bold: false, faint: true, italic: false, underline: false }
    }
    pub const fn fg_italic(color: Color) -> Self {
        Style { fg: Some(color), bg: None, bold: false, faint: false, italic: true, underline: false }
    }
    pub fn is_empty(&self) -> bool {
        self.fg.is_none() && self.bg.is_none() && !self.bold && !self.faint && !self.italic && !self.underline
    }
    pub fn ansi_prefix(&self) -> String {
        let mut codes: Vec<String> = Vec::new();
        if self.bold { codes.push("1".to_string()); }
        if self.faint { codes.push("2".to_string()); }
        if self.italic { codes.push("3".to_string()); }
        if self.underline { codes.push("4".to_string()); }
        if let Some(bg) = self.bg { codes.push(bg.bg_code().to_string()); }
        if let Some(fg) = self.fg { codes.push(fg.fg_code().to_string()); }
        codes.join(";")
    }
    pub fn paint(&self, text: &str) -> String {
        if self.is_empty() {
            return text.to_string();
        }
        format!("\x1b[{}m{}\x1b[0m", self.ansi_prefix(), text)
    }
}
RS
