use crate::style::Style;

#[derive(Clone, Debug, PartialEq)]
pub struct Seg {
    pub text: String,
    pub style: Option<Style>,
}

impl Seg {
    pub fn plain(text: impl Into<String>) -> Self { Seg { text: text.into(), style: None } }
    pub fn styled(text: impl Into<String>, style: Style) -> Self { Seg { text: text.into(), style: Some(style) } }
}

pub type Segs = Vec<Seg>;

pub fn render(segs: &[Seg]) -> String {
    let mut out = String::new();
    for seg in segs {
        match seg.style {
            Some(style) if !style.is_empty() => {
                out.push_str(&style.paint(&seg.text));
            }
            _ => out.push_str(&seg.text),
        }
    }
    out
}

/// Apply `f` to every unstyled segment independently; styled segments pass through.
pub fn apply_to_plain<F>(segs: Segs, mut f: F) -> Segs
where F: FnMut(&str) -> Segs {
    let mut out = Vec::new();
    for seg in segs {
        if seg.style.is_none() {
            out.extend(f(&seg.text));
        } else {
            out.push(seg);
        }
    }
    out
}

pub fn push_plain(out: &mut Segs, text: &str) {
    if !text.is_empty() {
        out.push(Seg::plain(text.to_string()));
    }
}
