}

impl Group {
    pub fn from_name(s: &str) -> Option<Group> {
        Some(match s {
            "numbers" => Group::Numbers,
            "urls" => Group::Urls,
            "pointers" => Group::Pointers,
            "dates" => Group::Dates,
            "paths" => Group::Paths,
            "quotes" => Group::Quotes,
            "key-value-pairs" => Group::KeyValuePairs,
            "uuids" => Group::Uuids,
            "ip-addresses" => Group::IpAddresses,
            "processes" => Group::Processes,
            "json" => Group::Json,
            _ => return None,
        })
    }
    pub fn all() -> Vec<Group> {
        vec![Group::Numbers, Group::Urls, Group::Pointers, Group::Dates, Group::Paths, Group::Quotes, Group::KeyValuePairs, Group::Uuids, Group::IpAddresses, Group::Processes, Group::Json]
    }
}

#[derive(Clone, Debug)]
pub struct CliKeyword {
    pub color_name: String,
    pub words: Vec<String>,
}

pub struct HighlighterSet {
    pub enabled: HashSet<Group>,
    pub disable_builtin_keywords: bool,
    // resolved styles
    pub number_style: Style,
    pub date_style: Style,
    pub time_style: Style,
