    pub pointer_x_style: Style,
    pub path_segment_style: Style,
    pub path_separator_style: Style,
    pub quote_style: Style,
    pub kv_key_style: Style,
    pub kv_separator_style: Style,
    pub uuid_number_style: Style,
    pub uuid_letter_style: Style,
    pub uuid_dash_style: Style,
    pub ip_number_style: Style,
    pub ip_letter_style: Style,
    pub ip_separator_style: Style,
    pub process_name_style: Style,
    pub process_id_style: Style,
    pub process_bracket_style: Style,
    pub json_key_style: Style,
    pub json_colon_style: Style,
    pub json_comma_style: Style,
    pub keyword_groups: Vec<keywords::KeywordGroup>,
    pub regexes: Vec<(Regex, Style)>,
}

pub enum BuildError {
    BothEnableDisable,
    RegexError(regex::Error),
}

impl HighlighterSet {
    pub fn build(
        enabled_values: Option<Vec<Group>>,
        disabled_values: Option<Vec<Group>>,
        disable_builtin_keywords: bool,
        cli_keywords: Vec<CliKeyword>,
        config: &ConfigToml,
    ) -> Result<Self, BuildError> {
        if enabled_values.is_some() && disabled_values.is_some() {
            return Err(BuildError::BothEnableDisable);
        }
        let enabled: HashSet<Group> = if let Some(list) = &enabled_values {
            list.iter().copied().collect()
        } else if let Some(list) = &disabled_values {
            let dis: HashSet<Group> = list.iter().copied().collect();
            Group::all().into_iter().filter(|g| !dis.contains(g)).collect()
        } else {
            Group::all().into_iter().collect()
        };

        // compile config regexes
        let mut regexes = Vec::new();
        for r in &config.regexes {
            match Regex::new(&r.regex) {
                Ok(re) => regexes.push((re, r.style)),
                Err(e) => return Err(BuildError::RegexError(e)),
            }
        }

        let keyword_groups = keywords::build_keyword_groups(disable_builtin_keywords, &cli_keywords, config);

        Ok(HighlighterSet {
            enabled,
            disable_builtin_keywords,
            number_style: config.numbers.number.unwrap_or(Style::fg(Color::Cyan)),
            date_style: config.dates.date.unwrap_or(Style::fg(Color::Magenta)),
            time_style: config.dates.time.unwrap_or(Style::fg(Color::Blue)),
            date_separator_style: config.dates.separator.unwrap_or(Style::faint()),
            date_zone_style: config.dates.zone.unwrap_or(Style::fg(Color::Red)),
            url_http_style: config.urls.http.unwrap_or(Style::fg_faint(Color::Red)),
            url_https_style: config.urls.https.unwrap_or(Style::fg_faint(Color::Green)),
            url_host_style: config.urls.host.unwrap_or(Style::fg_faint(Color::Blue)),
            url_path_style: config.urls.path.unwrap_or(Style::fg(Color::Blue)),
            pointer_number_style: config.pointers.number.unwrap_or(Style::fg_italic(Color::Blue)),
            pointer_letter_style: config.pointers.letter.unwrap_or(Style::fg_italic(Color::Magenta)),
            pointer_separator_style: config.pointers.separator.unwrap_or(Style::faint()),
            pointer_x_style: config.pointers.x.unwrap_or(Style::fg(Color::Red)),
            path_segment_style: config.paths.segment.unwrap_or(Style::fg(Color::Green)),
            path_separator_style: config.paths.separator.unwrap_or(Style::fg(Color::Yellow)),
            quote_style: config.quotes.style.unwrap_or(Style::fg(Color::Yellow)),
            kv_key_style: config.key_value_pairs.key.unwrap_or(Style::faint()),
            kv_separator_style: config.key_value_pairs.separator.unwrap_or(Style::fg(Color::White)),
            uuid_number_style: config.uuids.number.unwrap_or(Style::fg_italic(Color::Blue)),
            uuid_letter_style: config.uuids.letter.unwrap_or(Style::fg_italic(Color::Magenta)),
            uuid_dash_style: config.uuids.dash.unwrap_or(Style::fg(Color::Red)),
            ip_number_style: config.ip_addresses.number.unwrap_or(Style::fg_italic(Color::Blue)),
            ip_letter_style: config.ip_addresses.letter.unwrap_or(Style::fg_italic(Color::Magenta)),
            ip_separator_style: config.ip_addresses.separator.unwrap_or(Style::fg(Color::Red)),
            process_name_style: config.processes.name.unwrap_or(Style::fg(Color::Yellow)),
            process_id_style: config.processes.id.unwrap_or(Style::fg(Color::Cyan)),
            process_bracket_style: config.processes.bracket.unwrap_or(Style::fg(Color::Red)),
            json_key_style: config.json.key.unwrap_or(Style::faint()),
            json_colon_style: config.json.colon.unwrap_or(Style::faint()),
            json_comma_style: config.json.comma.unwrap_or(Style::faint()),
            keyword_groups,
            regexes,
        })
    }

    pub fn highlight(&self, line: &str) -> String {
        crate::segment::render(&self.highlight_segs(line))
    }

    pub fn highlight_segs(&self, line: &str) -> Segs {
        // JSON first
        let mut segs: Segs = if self.enabled.contains(&Group::Json) {
