{"command":"cat > src/highlight/numbers.rs <<'RS'
use crate::segment::{push_plain, Seg, Segs};
use crate::style::Style;
use regex::Regex;

pub fn is_ascii_word(b: u8) -> bool { b.is_ascii_alphanumeric() || b == b'_' }

pub fn apply(text: &str, style: Style) -> Segs {
    let re = Regex::new(r"[0-9]+(?:\.[0-9]+)?").unwrap();
    let bytes = text.as_bytes();
    let mut out: Segs = Vec::new();
    let mut last = 0usize;
    for m in re.find_iter(text) {
        let s = m.start(); let e = m.end();
        if s > 0 && is_ascii_word(bytes[s-1]) { continue; }
        if e < bytes.len() && is_ascii_word(bytes[e]) { continue; }
        push_plain(&mut out, &text[last..s]);
        out.push(Seg::styled(m.as_str().to_string(), style));
        last = e;
    }
    push_plain(&mut out, &text[last..]);
    out
