use crate::config::ConfigToml;
use crate::segment::{push_plain, Seg, Segs};
use crate::style::{Color, Style};

#[derive(Clone, Debug)]
pub struct KeywordGroup {
    pub words: Vec<String>,
    pub style: Style,
}

fn is_ascii_word_char(c: char) -> bool { c.is_ascii_alphanumeric() || c == '_' }

pub fn build_keyword_groups(disable_builtin: bool, cli: &[super::CliKeyword], config: &ConfigToml) -> Vec<KeywordGroup> {
    let mut groups: Vec<KeywordGroup> = Vec::new();
    if !disable_builtin {
        for (words, style) in builtin::builtin_keyword_groups() {
            groups.push(KeywordGroup { words: words.iter().map(|s| s.to_string()).collect(), style });
        }
    }
    for kw in &config.keywords {
        groups.push(KeywordGroup { words: kw.words.clone(), style: kw.style });
    }
    for ck in cli {
        if let Some(color) = cli_color(&ck.color_name) {
            groups.push(KeywordGroup { words: ck.words.clone(), style: Style::fg(color) });
        }
    }
    // Sort by style (stable)
    groups.sort_by(|a, b| a.style.cmp(&b.style));
    groups
}

pub fn cli_color(name: &str) -> Option<Color> {
    match name.to_ascii_lowercase().as_str() {
        "red" => Some(Color::Red),
        "green" => Some(Color::Green),
        "yellow" => Some(Color::Yellow),
        "blue" => Some(Color::Blue),
        "magenta" => Some(Color::Magenta),
        "cyan" => Some(Color::Cyan),
        _ => None,
    }
}

pub fn apply_keyword_group(text: &str, group: &KeywordGroup) -> Segs {
    // Collect candidate matches
    let chars: Vec<(usize, char)> = text.char_indices().collect();
    // helper to get char before byte index and after
    let byte_to_char_idx = |byte: usize| -> Option<usize> {
        chars.iter().position(|(b, _)| *b == byte)
    };
    // Build candidates (start_byte, end_byte, word_order)
    let mut candidates: Vec<(usize, usize, usize)> = Vec::new();
    for (order, word) in group.words.iter().enumerate() {
        if word.is_empty() { continue; }
        let mut start_search = 0usize;
        while let Some(found) = text[start_search..].find(word.as_str()) {
            let s = start_search + found;
            let e = s + word.len();
            // prev char
            let prev_ok = if s == 0 { true } else {
                let prev_char = text[..s].chars().last().unwrap();
                !is_ascii_word_char(prev_char)
            };
            let next_ok = if e >= text.len() { true } else {
                let next_char = text[e..].chars().next().unwrap();
                !is_ascii_word_char(next_char)
            };
            if prev_ok && next_ok {
                candidates.push((s, e, order));
            }
            // advance by one char
            let next_pos = s + word.chars().next().map(|c| c.len_utf8()).unwrap_or(1);
            if next_pos > text.len() { break; }
            start_search = next_pos;
            if start_search >= text.len() && word.len() > 0 {
                // still allow check at end? find will fail
                if start_search > text.len() { break; }
            }
        }
        let _ = byte_to_char_idx;
    }
    candidates.sort_by(|a, b| a.0.cmp(&b.0).then(a.2.cmp(&b.2)));
    let mut out: Segs = Vec::new();
    let mut last = 0usize;
    let mut cursor = 0usize;
    for (s, e, _order) in candidates {
        if s < cursor { continue; }
        push_plain(&mut out, &text[last..s]);
        let matched = &text[s..e];
        let display = if group.style.bg.is_some() {
            format!(" {} ", matched)
        } else {
            matched.to_string()
        };
        out.push(Seg::styled(display, group.style));
        last = e;
        cursor = e;
    }
    push_plain(&mut out, &text[last..]);
    out
}
