        let mut start_search = 0usize;
        while let Some(found) = text[start_search..].find(word.as_str()) {
            let s = start_search + found;
            let e = s + word.len();
            // prev char
            let prev_ok = if s == 0 { true } else {
                let prev_char = text[..s].chars().last().unwrap();
                !is_ascii_word_char(prev_char)
            };
            let next_ok = if e >= text.len() { true } else {
                let next_char = text[e..].chars().next().unwrap();
                !is_ascii_word_char(next_char)
            };
            if prev_ok && next_ok {
                candidates.push((s, e, order));
            }
            // advance by one char
            let next_pos = s + word.chars().next().map(|c| c.len_utf8()).unwrap_or(1);
            if next_pos > text.len() { break; }
            start_search = next_pos;
            if start_search >= text.len() && word.len() > 0 {
                // still allow check at end? find will fail
                if start_search > text.len() { break; }
            }
        }
        let _ = byte_to_char_idx;
    }
    candidates.sort_by(|a, b| a.0.cmp(&b.0).then(a.2.cmp(&b.2)));
    let mut out: Segs = Vec::new();
    let mut last = 0usize;
    let mut cursor = 0usize;
    for (s, e, _order) in candidates {
        if s < cursor { continue; }
        push_plain(&mut out, &text[last..s]);
        let matched = &text[s..e];
        let display = if group.style.bg.is_some() {
            format!(" {} ", matched)
        } else {
            matched.to_string()
        };
        out.push(Seg::styled(display, group.style));
        last = e;
        cursor = e;
    }
    push_plain(&mut out, &text[last..]);
    out
}
