use crate::segment::{push_plain, Seg, Segs};
use crate::style::{Color, Style};
use regex::Regex;

fn is_query_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || matches!(c, '%' | '+' | '-' | '.' | '_' | '~')
}

pub fn apply(text: &str, styles: (Style, Style, Style, Style)) -> Segs {
    let (http_style, https_style, host_style, path_style) = styles;
    let re = Regex::new(r"(?P<scheme>https?)://(?P<host>[A-Za-z0-9._-]+)(?P<path>/[A-Za-z0-9%+\-._~/]*)?").unwrap();
    let mut out: Segs = Vec::new();
    let mut last = 0usize;
    for caps in re.captures_iter(text) {
        let whole = caps.get(0).unwrap();
        push_plain(&mut out, &text[last..whole.start()]);
        let scheme = caps.name("scheme").unwrap().as_str();
        let scheme_style = if scheme == "https" { https_style } else { http_style };
        out.push(Seg::styled(scheme.to_string(), scheme_style));
        push_plain(&mut out, "://");
        out.push(Seg::styled(caps.name("host").unwrap().as_str().to_string(), host_style));
        // path segment is always emitted (empty if absent)
        let path_text = caps.name("path").map(|m| m.as_str().to_string()).unwrap_or_default();
        out.push(Seg::styled(path_text, path_style));
        last = whole.end();
        // Query parsing
        let rest = &text[last..];
        let mut qpos = 0usize; // offset in rest consumed by query handling
        // We emit plain for non-matching chars individually as part of subsequent loop; but here
        // we need to parse pairs starting at current position. Any '?' that does not start a pair
        // stays plain (will be emitted as part of plain text before next URL) - however our `last`
        // pointer must advance past consumed query pairs only.
        loop {
            let remaining = &rest[qpos..];
            if remaining.is_empty() { break; }
            let first = remaining.chars().next().unwrap();
            if first != '?' && first != '&' { break; }
            // try parse pair at this separator
            let after_sep = &remaining[1..];
            let key_end = after_sep.find(|c: char| !is_query_char(c)).unwrap_or(after_sep.len());
            let key = &after_sep[..key_end];
            if key_end < after_sep.len() && after_sep.as_bytes()[key_end] == b'=' {
                let after_eq = &after_sep[key_end+1..];
                let val_end = after_eq.find(|c: char| !is_query_char(c)).unwrap_or(after_eq.len());
                let value = &after_eq[..val_end];
                // emit segments
                out.push(Seg::styled(first.to_string(), Style::fg(Color::Red)));
                out.push(Seg::styled(key.to_string(), Style::fg(Color::Magenta)));
                out.push(Seg::styled("=".to_string(), Style::fg(Color::Red)));
                out.push(Seg::styled(value.to_string(), Style::fg(Color::Cyan)));
                let consumed = 1 + key_end + 1 + val_end;
                qpos += consumed;
                last += consumed;
            } else {
                // If this is '?' and next is '&', leave '?' plain but advance one char in plain handling.
                // We achieve this by breaking if first=='?' and remaining starts with "?&"
                if first == '?' && remaining.len() >= 2 && remaining.as_bytes()[1] == b'&' {
                    // leave '?' as plain: move last forward by 1 but need to emit it as plain
                    push_plain(&mut out, "?");
                    qpos += 1;
                    last += 1;
                    continue;
                }
                break;
            }
        }
    }
    push_plain(&mut out, &text[last..]);
    out
}
