fn is_ascii_word(b: u8) -> bool { b.is_ascii_alphanumeric() || b == b'_' }
fn is_hex(b: u8) -> bool { b.is_ascii_hexdigit() }

pub fn apply(text: &str, styles: (Style, Style, Style, Style)) -> Segs {
