use crate::segment::{Seg, Segs};
use crate::style::Style;
use serde_json::Value;

pub fn try_format(line: &str, key_style: Style, colon_style: Style, comma_style: Style) -> Option<Segs> {
    let value: Value = serde_json::from_str(line).ok()?;
    let faint = Style::faint();
    let mut out: Segs = Vec::new();
    format_value(&value, faint, key_style, colon_style, comma_style, &mut out);
    Some(out)
}

fn format_value(v: &Value, faint: Style, key_style: Style, colon_style: Style, comma_style: Style, out: &mut Segs) {
    match v {
        Value::Null => out.push(Seg::plain("null")),
        Value::Bool(b) => out.push(Seg::plain(if *b { "true" } else { "false" })),
        Value::Number(n) => out.push(Seg::plain(n.to_string())),
        Value::String(s) => {
            out.push(Seg::styled("\"".to_string(), faint));
            if !s.is_empty() { out.push(Seg::plain(s.clone())); }
            out.push(Seg::styled("\"".to_string(), faint));
        }
        Value::Array(arr) => {
            out.push(Seg::styled("[".to_string(), faint));
            for (i, item) in arr.iter().enumerate() {
                if i > 0 {
                    out.push(Seg::styled(",".to_string(), comma_style));
                    out.push(Seg::plain(" "));
                }
                format_value(item, faint, key_style, colon_style, comma_style, out);
            }
            out.push(Seg::styled("]".to_string(), faint));
        }
        Value::Object(map) => {
            out.push(Seg::styled("{".to_string(), faint));
            for (i, (k, val)) in map.iter().enumerate() {
                if i > 0 {
                    out.push(Seg::styled(",".to_string(), comma_style));
                    out.push(Seg::plain(" "));
                } else {
                    out.push(Seg::plain(" "));
                }
                out.push(Seg::styled("\"".to_string(), faint));
                // key content is a styled segment even when empty
                out.push(Seg::styled(k.clone(), key_style));
                out.push(Seg::styled("\"".to_string(), faint));
                out.push(Seg::styled(":".to_string(), colon_style));
                out.push(Seg::plain(" "));
                format_value(val, faint, key_style, colon_style, comma_style, out);
            }
            out.push(Seg::plain(" "));
            out.push(Seg::styled("}".to_string(), faint));
        }
    }
}
