use crate::segment::{Seg, Segs};
use crate::style::Style;
use std::net::Ipv6Addr;

type Styles = (Style, Style, Style);

fn is_ascii_word(b: u8) -> bool { b.is_ascii_alphanumeric() || b == b'_' }

#[derive(Debug)]
enum Candidate {
    Accept { end: usize, segs: Segs },
    Reject { end: usize },
}

pub fn apply(text: &str, styles: Styles) -> Segs {
    let mut out: Segs = Vec::new();
    let mut plain = String::new();
    let bytes = text.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        // only try at char boundaries; our sets are ascii, but step by char
        match try_candidate(text, i, styles) {
            Some(Candidate::Accept { end, segs }) => {
                if !plain.is_empty() { out.push(Seg::plain(std::mem::take(&mut plain))); }
                out.extend(segs);
                i = end;
            }
            Some(Candidate::Reject { end }) => {
                plain.push_str(&text[i..end]);
                i = end;
            }
            None => {
                let ch_len = text[i..].chars().next().map(|c| c.len_utf8()).unwrap_or(1);
                plain.push_str(&text[i..i+ch_len]);
                i += ch_len;
            }
        }
    }
    if !plain.is_empty() { out.push(Seg::plain(plain)); }
    out
}

fn try_candidate(text: &str, pos: usize, styles: Styles) -> Option<Candidate> {
    // Try IPv6 first if there's a colon nearby in the run
    if let Some(c) = try_ipv6(text, pos, styles) { return Some(c); }
    try_ipv4(text, pos, styles)
}

fn parse_octets(parts: &[&str]) -> Option<Vec<u32>> {
    let mut v = Vec::new();
    for p in parts { v.push(p.parse::<u32>().ok()?); }
    Some(v)
}

fn try_ipv4(text: &str, pos: usize, styles: Styles) -> Option<Candidate> {
    let (number_style, _letter_style, separator_style) = styles;
    let rest = &text[pos..];
    let bytes = text.as_bytes();
    if pos > 0 && is_ascii_word(bytes[pos-1]) { return None; }
    // match digits.digits.digits.digits manually
    let rb = rest.as_bytes();
    let mut idx = 0usize;
    let mut octet_strs: Vec<&str> = Vec::new();
    for part in 0..4 {
        let start = idx;
        while idx < rb.len() && rb[idx].is_ascii_digit() && idx - start < 3 { idx += 1; }
        if idx == start { return None; }
        // if there's a 4th digit, this candidate structure fails at this pos
        if idx < rb.len() && rb[idx].is_ascii_digit() { return None; }
        octet_strs.push(&rest[start..idx]);
        if part < 3 {
            if idx >= rb.len() || rb[idx] != b'.' { return None; }
            idx += 1;
        }
    }
    let ip_end_rel = idx;
    let ip_end = pos + ip_end_rel;
    let octets = parse_octets(&octet_strs)?;
    let octets_valid = octets.iter().all(|o| *o <= 255);
    // Check CIDR
    let mut cidr: Option<(usize, usize, &str)> = None; // rel start of '/', rel end, prefix str
    if ip_end_rel < rb.len() && rb[ip_end_rel] == b'/' {
        let pstart = ip_end_rel + 1;
        let mut pend = pstart;
        while pend < rb.len() && rb[pend].is_ascii_digit() && pend - pstart < 2 { pend += 1; }
        if pend > pstart {
            cidr = Some((ip_end_rel, pend, &rest[pstart..pend]));
        }
    }
    if let Some((slash_rel, cidr_end_rel, prefix_str)) = cidr {
        let _ = slash_rel;
        let after_cidr_pos = pos + cidr_end_rel;
        let after_is_word = after_cidr_pos < bytes.len() && is_ascii_word(bytes[after_cidr_pos]);
        if !after_is_word {
            // full CIDR candidate decision
            let prefix_val: i64 = prefix_str.parse().unwrap_or(-1);
            if octets_valid && (0..=32).contains(&prefix_val) {
                let mut segs: Segs = Vec::new();
                for (i, oct) in octet_strs.iter().enumerate() {
                    if i > 0 { segs.push(Seg::styled(".".to_string(), separator_style)); }
                    segs.push(Seg::styled(oct.to_string(), number_style));
                }
                segs.push(Seg::styled("/".to_string(), separator_style));
                segs.push(Seg::styled(prefix_str.to_string(), number_style));
                return Some(Candidate::Accept { end: after_cidr_pos, segs });
            } else {
                return Some(Candidate::Reject { end: after_cidr_pos });
            }
        } else {
            // fall through to IP-only
            if !octets_valid {
                return Some(Candidate::Reject { end: ip_end });
            }
            // right boundary for IP is '/' (non-word), ok
            let mut segs: Segs = Vec::new();
            for (i, oct) in octet_strs.iter().enumerate() {
                if i > 0 { segs.push(Seg::styled(".".to_string(), separator_style)); }
                segs.push(Seg::styled(oct.to_string(), number_style));
            }
            return Some(Candidate::Accept { end: ip_end, segs });
        }
    }
    // no CIDR digits
    if !octets_valid {
        // only reject if next char after IP is not a word? Actually 256.1.1.1 at end or followed by separator
        // Determine right boundary: if next char is ascii word, the regex would fail anyway and a subcandidate could exist?
        return Some(Candidate::Reject { end: ip_end });
    }
    if ip_end < bytes.len() && is_ascii_word(bytes[ip_end]) { return None; }
    let mut segs: Segs = Vec::new();
    for (i, oct) in octet_strs.iter().enumerate() {
        if i > 0 { segs.push(Seg::styled(".".to_string(), separator_style)); }
        segs.push(Seg::styled(oct.to_string(), number_style));
    }
    Some(Candidate::Accept { end: ip_end, segs })
}

fn is_hex_colon_dot(c: char) -> bool {
    c.is_ascii_hexdigit() || c == ':' || c == '.'
}

fn try_ipv6(text: &str, pos: usize, styles: Styles) -> Option<Candidate> {
    let (number_style, letter_style, separator_style) = styles;
    // left char cannot be hex/colon/dot
    if pos > 0 {
        let prev = text[..pos].chars().last().unwrap();
        if is_hex_colon_dot(prev) { return None; }
    }
    let rest = &text[pos..];
    // quick check: must start with hex digit or ':'
    let first = rest.chars().next()?;
    if !(first.is_ascii_hexdigit() || first == ':') { return None; }
    // collect run of hex/colon/dot chars (byte length)
    let mut run_end = 0usize;
    for (off, ch) in rest.char_indices() {
        if is_hex_colon_dot(ch) { run_end = off + ch.len_utf8(); } else { break; }
    }
    if run_end == 0 { return None; }
    let run = &rest[..run_end];
    // Try longest to shortest substrings that align to char boundaries in run
    // Candidate lengths are byte indices of run ( all ascii so bytes == chars )
    for len in (1..=run.len()).rev() {
        let cand = &run[..len];
        if !cand.contains(':') { continue; }
        if cand == "::" { continue; }
        if cand.ends_with(':') && !cand.ends_with("::") { continue; }
        // parse Ipv6
        if cand.parse::<Ipv6Addr>().is_err() { continue; }
        // right boundary: char after candidate in original text
        let abs_end = pos + len;
        if abs_end < text.len() {
            let next = text[abs_end..].chars().next().unwrap();
            if is_hex_colon_dot(next) { continue; }
        }
        // Accept
        let mut segs: Segs = Vec::new();
        for ch in cand.chars() {
            if ch.is_ascii_digit() {
                segs.push(Seg::styled(ch.to_string(), number_style));
            } else if ch.is_ascii_hexdigit() {
                segs.push(Seg::styled(ch.to_string(), letter_style));
            } else {
                // ':' or '.'
                segs.push(Seg::styled(ch.to_string(), separator_style));
            }
        }
        let mut end = abs_end;
        // optional CIDR /digits up to 3
        if end < text.len() && text.as_bytes()[end] == b'/' {
            let after = &text[end+1..];
            let mut dlen = 0usize;
            for b in after.bytes() {
                if b.is_ascii_digit() && dlen < 3 { dlen += 1; } else { break; }
            }
            if dlen > 0 {
                segs.push(Seg::styled("/".to_string(), separator_style));
                segs.push(Seg::styled(after[..dlen].to_string(), number_style));
                end += 1 + dlen;
            }
        }
        return Some(Candidate::Accept { end, segs });
    }
    None
}
