use crate::style::{Color, Style};
use std::io::IsTerminal;

#[derive(Clone, Copy, PartialEq)]
pub enum Severity { Error, Warning }

pub struct AppError {
    pub message: String,
    pub severity: Severity,
    pub code: Option<String>,
    pub source: Option<String>,
    pub help: Option<String>,
}

impl AppError {
    pub fn simple(message: impl Into<String>) -> Self {
        AppError { message: message.into(), severity: Severity::Error, code: None, source: None, help: None }
    }
    pub fn warning(message: impl Into<String>) -> Self {
        AppError { message: message.into(), severity: Severity::Warning, code: None, source: None, help: None }
    }
    pub fn with_source(message: impl Into<String>, source: impl Into<String>) -> Self {
        AppError { message: message.into(), severity: Severity::Error, code: None, source: Some(source.into()), help: None }
    }
    pub fn with_code(code: &str, message: impl Into<String>, source: Option<String>) -> Self {
        AppError { message: message.into(), severity: Severity::Error, code: Some(code.to_string()), source, help: None }
    }
    pub fn with_help(message: impl Into<String>, source: impl Into<String>, help: impl Into<String>) -> Self {
        AppError { message: message.into(), severity: Severity::Error, code: None, source: Some(source.into()), help: Some(help.into()) }
    }
}

fn use_color() -> bool {
    let force = (std::env::var_os("FORCE_COLOR").map(|v| v != "0").unwrap_or(false))
        || (std::env::var_os("CLICOLOR_FORCE").map(|v| v != "0").unwrap_or(false));
    if force { return true; }
    if std::env::var_os("NO_COLOR").is_some() { return false; }
    if !std::io::stderr().is_terminal() { return false; }
    match std::env::var("TERM") { Ok(t) => t != "dumb", Err(_) => true }
}

fn visible_len(s: &str) -> usize {
    // count chars ignoring ANSI escape sequences
    let mut count = 0usize;
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '\x1b' {
            for c2 in chars.by_ref() { if c2 == 'm' { break; } }
        } else { count += 1; }
    }
    count
}

fn wrap_text(text: &str, first_prefix_len: usize, cont_prefix_len: usize, width: usize) -> Vec<String> {
    // word wrap, returns lines without prefixes
    let mut lines: Vec<String> = Vec::new();
    let mut current = String::new();
    let mut current_len = first_prefix_len;
    let limit = width;
    for word in text.split(' ') {
        let wlen = visible_len(word);
        if current.is_empty() {
            current.push_str(word);
            current_len += wlen;
        } else if current_len + 1 + wlen <= limit {
            current.push(' ');
            current.push_str(word);
            current_len += 1 + wlen;
        } else {
            lines.push(std::mem::take(&mut current));
            current.push_str(word);
            current_len = cont_prefix_len + wlen;
        }
    }
    if !current.is_empty() || lines.is_empty() { lines.push(current); }
    lines
}

pub fn render_error(e: &AppError) -> String {
    let color = use_color();
    let (red, yellow, cyan, reset) = if color { ("\x1b[31m", "\x1b[33m", "\x1b[36m", "\x1b[0m") } else { ("", "", "", "") };
    let symbol_plain = match e.severity { Severity::Error => "×", Severity::Warning => "⚠" };
    let symbol = if color {
        match e.severity { Severity::Error => format!("{}{}{}", red, symbol_plain, reset), Severity::Warning => format!("{}{}{}", yellow, symbol_plain, reset) }
    } else { symbol_plain.to_string() };
    let mut out = String::new();
    // first line(s)
    let message_lines: Vec<&str> = e.message.split('\n').collect();
    if let Some(code) = &e.code {
        if color { out.push_str(&format!("Error: {}{}{}\n\n", red, code, reset)); }
        else { out.push_str(&format!("Error: {}\n\n", code)); }
        // message first line
        out.push_str(&format!("  {} {}", symbol, message_lines.get(0).copied().unwrap_or("")));
        out.push('\n');
        for line in message_lines.iter().skip(1) {
            if color { out.push_str(&format!("  {}│{} {}\n", red, reset, line)); }
            else { out.push_str(&format!("  │ {}\n", line)); }
        }
    } else {
        // "Error:   × first"
        // If message is a single long line, wrap it like miette does
        if message_lines.len() == 1 && visible_len(message_lines[0]) + 11 > 80 {
            let wrapped = wrap_text(message_lines[0], 11, 4, 80);
            for (i, line) in wrapped.iter().enumerate() {
                if i == 0 { out.push_str(&format!("Error:   {} {}\n", symbol, line)); }
                else if color { out.push_str(&format!("  {}│{} {}\n", red, reset, line)); }
                else { out.push_str(&format!("  │ {}\n", line)); }
            }
        } else {
            out.push_str(&format!("Error:   {} {}", symbol, message_lines.get(0).copied().unwrap_or("")));
            out.push('\n');
            for line in message_lines.iter().skip(1) {
                if color { out.push_str(&format!("  {}│{} {}\n", red, reset, line)); }
                else { out.push_str(&format!("  │ {}\n", line)); }
            }
            // If the underlying message ended with a newline, split produces a trailing empty
            // entry which is included above as a "  │ " line. That matches miette for TOML errors.
            // However for messages built from io errors without trailing newline this doesn't happen.
            let _ = Style::fg(Color::Red);
        }
    }
    if let Some(source) = &e.source {
        let slines: Vec<&str> = source.split('\n').collect();
        for (i, line) in slines.iter().enumerate() {
            if i == 0 {
                if color { out.push_str(&format!("{}  ╰─▶ {}{}\n", red, reset, line)); }
                else { out.push_str(&format!("  ╰─▶ {}\n", line)); }
            } else {
                if color { out.push_str(&format!("{}      {}{}\n", red, reset, line)); }
                else { out.push_str(&format!("      {}\n", line)); }
            }
        }
    }
    if let Some(help) = &e.help {
        let wrapped = wrap_text(help, 10, 8, 80);
        for (i, line) in wrapped.iter().enumerate() {
            if i == 0 {
                if color { out.push_str(&format!("{}  help: {}{}\n", cyan, reset, line)); }
                else { out.push_str(&format!("  help: {}\n", line)); }
            } else {
                out.push_str(&format!("        {}\n", line));
            }
        }
    }
    out.push('\n');
    out
}
RS
echo ok"}

