use crate::errors::AppError;

#[derive(Clone, Debug)]
pub struct PagerCommand {
    pub program: String,
    pub args: Vec<String>,
}

#[derive(Clone, Debug)]
pub enum Pager {
    DefaultLess { follow: bool },
    Custom(PagerCommand),
}

pub fn build_pager(custom: Option<&str>, follow: bool, file_path: &str) -> Result<Pager, AppError> {
    match custom {
        Some(s) => {
            let cmd = parse_custom(s, file_path)?;
            Ok(Pager::Custom(cmd))
        }
        None => Ok(Pager::DefaultLess { follow }),
    }
}

pub fn parse_custom(pager_str: &str, file_path: &str) -> Result<PagerCommand, AppError> {
    let replaced = pager_str.replace("[FILE]", file_path);
    let tokens = split_shell_words(&replaced)
        .ok_or_else(|| AppError::simple("Could not parse custom pager command"))?;
    if tokens.len() < 2 {
        return Err(AppError::simple("Could not parse custom pager command"));
    }
    Ok(PagerCommand { program: tokens[0].clone(), args: tokens[1..].to_vec() })
}

pub fn command_for(pager: &Pager, file_path: &str) -> (String, Vec<String>) {
    match pager {
        Pager::DefaultLess { follow } => {
            let mut args: Vec<String> = Vec::new();
            if *follow { args.push("+F".to_string()); }
            args.push("--ignore-case".to_string());
            args.push("--RAW-CONTROL-CHARS".to_string());
            args.push("--".to_string());
            args.push(file_path.to_string());
            ("less".to_string(), args)
        }
        Pager::Custom(cmd) => {
            // cmd was built with a placeholder path; rebuild with real path if needed is done by caller
            (cmd.program.clone(), cmd.args.clone())
        }
    }
}

pub fn split_shell_words(input: &str) -> Option<Vec<String>> {
    let mut tokens: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut token_started = false;
    let mut chars = input.chars().peekable();
    #[derive(PartialEq)]
    enum State { Normal, Single, Double }
    let mut state = State::Normal;
    while let Some(c) = chars.next() {
        match state {
            State::Normal => {
                if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                    if token_started { tokens.push(std::mem::take(&mut cur)); token_started = false; }
                } else if c == '\'' {
                    state = State::Single; token_started = true;
                } else if c == '"' {
                    state = State::Double; token_started = true;
                } else if c == '\\' {
                    token_started = true;
                    match chars.next() { Some(n) => cur.push(n), None => return None }
                } else { token_started = true; cur.push(c); }
            }
            State::Single => {
                if c == '\'' { state = State::Normal; } else { cur.push(c); }
            }
            State::Double => {
                if c == '"' { state = State::Normal; }
                else if c == '\\' {
                    match chars.next() { Some(n) => cur.push(n), None => return None }
                } else { cur.push(c); }
            }
        }
    }
    if state != State::Normal { return None; }
    if token_started { tokens.push(cur); }
    Some(tokens)
}
