use std::fs;
use std::io;
use std::path::PathBuf;

pub struct TempOutput {
    pub dir: PathBuf,
    pub file_path: PathBuf,
    pub file: fs::File,
}

fn random_bytes(n: usize) -> Vec<u8> {
    fs::read("/dev/urandom").map(|v| v.into_iter().cycle().take(n).collect()).unwrap_or_else(|_| {
        let t = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_nanos()).unwrap_or(0);
        (0..n).map(|i| ((t >> ((i % 8) * 8)) & 0xff) as u8 ^ (i as u8).wrapping_mul(37)).collect()
    })
}

pub fn create_temp_output() -> io::Result<TempOutput> {
    let base = std::env::temp_dir();
    let chars: Vec<char> = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789".chars().collect();
    let rnd = random_bytes(6);
    let suffix: String = rnd.iter().map(|b| chars[(*b as usize) % chars.len()]).collect();
    let dir = base.join(format!(".tmp{}", suffix));
    fs::create_dir(&dir)?;
    // uuid v4
    let mut b = random_bytes(16);
    if b.len() < 16 { b.resize(16, 0); }
    b[6] = (b[6] & 0x0f) | 0x40;
    b[8] = (b[8] & 0x3f) | 0x80;
    let uuid = format!(
        "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
        b[0], b[1], b[2], b[3], b[4], b[5], b[6], b[7], b[8], b[9], b[10], b[11], b[12], b[13], b[14], b[15]
    );
    let file_path = dir.join(format!("tailspin.temp.{}", uuid));
    let file = fs::OpenOptions::new().write(true).create_new(true).open(&file_path)?;
    Ok(TempOutput { dir, file_path, file })
}

impl Drop for TempOutput {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.file_path);
        let _ = fs::remove_dir(&self.dir);
    }
}
