use crate::config::ConfigToml;
use crate::errors::AppError;
use crate::highlight::{BuildError, CliKeyword, Group, HighlighterSet};
use crate::pager::{build_pager, Pager};
use crate::style::{Color, Style};
use clap::ArgMatches;
use std::fs::{self, File};
use std::io::{self, BufRead, BufReader, IsTerminal, Read, Seek, SeekFrom, Write};
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::Arc;
use std::time::{Duration, Instant};

struct Args {
    file: Option<PathBuf>,
    follow: bool,
    print: bool,
    config_path: Option<PathBuf>,
    exec: Option<String>,
    highlights: Vec<CliKeyword>,
    enable: Option<Vec<Group>>,
    disable: Option<Vec<Group>>,
    disable_builtin_keywords: bool,
    pager: Option<String>,
}

fn extract_args(m: &ArgMatches) -> Args {
    let file = m.get_one::<PathBuf>("FILE").cloned();
    let enable: Option<Vec<Group>> = m.get_many::<String>("enable").map(|vals| {
        vals.filter_map(|s| Group::from_name(s)).collect()
    });
    let disable: Option<Vec<Group>> = m.get_many::<String>("disable").map(|vals| {
        vals.filter_map(|s| Group::from_name(s)).collect()
    });
    // Presence detection: get_many returns Some even if ... clap ensures non-empty values for Append with delimiter.
    Args {
        file,
        follow: m.get_flag("follow"),
        print: m.get_flag("print"),
        config_path: m.get_one::<PathBuf>("config_path").cloned(),
        exec: m.get_one::<String>("exec").cloned(),
        highlights: m.get_many::<CliKeyword>("highlight").map(|v| v.cloned().collect()).unwrap_or_default(),
        enable,
        disable,
        disable_builtin_keywords: m.get_flag("disable_builtin_keywords"),
        pager: m.get_one::<String>("pager").cloned(),
    }
}

#[derive(Clone)]
enum Source {
    File(PathBuf),
    Stdin,
    Exec(String),
}

pub fn run(matches: &ArgMatches) -> Result<(), AppError> {
    let args = extract_args(matches);

    if args.file.is_some() && args.exec.is_some() {
        return Err(AppError::simple(format!(
            "Cannot read from both file and {}",
            Style::fg(Color::Magenta).paint("--listen-command")
        )));
    }

    // Determine source
    let source: Source;
    if let Some(path) = &args.file {
        if !path.exists() {
            return Err(AppError::warning(format!(
                "{}: No such file or directory",
                Style::fg(Color::Yellow).paint(&path.display().to_string())
            )));
        }
        if !path.is_file() {
            return Err(AppError::simple("Path is not a file"));
        }
        source = Source::File(path.clone());
    } else if let Some(exec_cmd) = &args.exec {
        if io::stdin().is_terminal() {
            source = Source::Exec(exec_cmd.clone());
        } else {
            source = Source::Stdin;
        }
    } else {
        if io::stdin().is_terminal() {
            println!("Missing filename ({} for help)", Style::fg(Color::Cyan).paint("tspin --help"));
            return Ok(());
        }
        source = Source::Stdin;
    }

    let is_stdin = matches!(source, Source::Stdin);
    let print_mode = args.print || is_stdin;

    // Determine pager kind (validation before enable/disable and config)
    // Use a placeholder path for custom parsing validation.
    let placeholder_path = "/tmp/.tmpxxxxxx/tailspin.temp.00000000-0000-4000-8000-000000000000";
    let follow_for_less = match &source {
        Source::Exec(_) => true,
        _ => args.follow,
    };
    let pager_kind: Option<Pager> = if !print_mode {
        Some(build_pager(args.pager.as_deref(), follow_for_less, placeholder_path)?)
    } else {
        None
    };

    // enable/disable conflict check (before config)
    if args.enable.is_some() && args.disable.is_some() {
        return Err(AppError::simple("cannot both enable and disable highlighters"));
    }

    // Load config
    let config = load_config(args.config_path.as_deref())?;

    // Build highlighters
    let highs = match HighlighterSet::build(
        args.enable.clone(),
        args.disable.clone(),
        args.disable_builtin_keywords,
        args.highlights.clone(),
        &config,
    ) {
        Ok(h) => Arc::new(h),
        Err(BuildError::BothEnableDisable) => {
            return Err(AppError::simple("cannot both enable and disable highlighters"))
        }
        Err(BuildError::RegexError(e)) => {
            return Err(AppError {
                message: format!("Regex error: {}", e),
                severity: crate::errors::Severity::Error,
                code: None,
                source: Some(e.to_string()),
                help: Some("Verify that your regex pattern is valid.".to_string()),
            })
        }
    };

    match source {
        Source::Stdin => {
            let stdin = io::stdin();
            let lock = stdin.lock();
            process_pipe(lock, &highs, &mut stdout_writer())
        }
        Source::File(path) => {
            handle_file(&path, print_mode, pager_kind, args.pager.as_deref(), follow_for_less, &highs)
        }
        Source::Exec(cmd) => {
            if print_mode {
                handle_exec_print(&cmd, &highs)
            } else {
                handle_exec_pager(&cmd, pager_kind, args.pager.as_deref(), &highs)
            }
        }
    }
}

fn stdout_writer() -> impl Write {
    io::BufWriter::new(io::stdout())
}

fn load_config(custom: Option<&Path>) -> Result<ConfigToml, AppError> {
    if let Some(path) = custom {
        if !path.exists() {
            return Err(AppError::simple("could not find the TOML file"));
        }
        let content = fs::read_to_string(path).map_err(|e| {
            AppError::with_source(format!("could not read the TOML file: {}", e), e.toString())
        })?;
        parse_toml(&content)
    } else {
        let default_path = default_config_path()?;
        if default_path.exists() {
            let content = fs::read_to_string(&default_path).map_err(|e| {
                AppError::with_source(format!("could not read the TOML file: {}", e), e.toString())
            })?;
            parse_toml(&content)
        } else {
            Ok(ConfigToml::default())
        }
    }
}

// helper trait to avoid typo issues
trait ToString2 { fn toString(&self) -> String; }
impl ToString2 for io::Error { fn toString(&self) -> String { self.to_string() } }

fn parse_toml(content: &str) -> Result<ConfigToml, AppError> {
    toml::from_str::<ConfigToml>(content).map_err(|e| AppError::simple(format!("{}", e)))
}

fn default_config_path() -> Result<PathBuf, AppError> {
    match std::env::var("XDG_CONFIG_HOME") {
        Ok(val) => Ok(PathBuf::from(val).join("tailspin/theme.toml")),
        Err(_) => {
            let home = std::env::var("HOME").map_err(|e| {
                AppError::with_source(
                    format!("could not determine the home environment: {}", e),
                    e.to_string(),
                )
            })?;
            Ok(PathBuf::from(home).join(".config/tailspin/theme.toml"))
        }
    }
}

// ---------- File handling ----------

struct FileInitial {
    complete_lines: Vec<String>,
    partial: Option<Vec<u8>>,
    content_len: u64,
}

fn failed_signal_err() -> AppError {
    AppError::with_help(
        "Failed to receive initial-read-complete signal",
        "channel closed",
        "Ensure the IO task completes correctly and signals initial read completion.",
    )
}

fn could_not_read_next_line(source: String) -> AppError {
    AppError::with_source("Could not read next line", source)
}

fn read_file_initial(path: &Path) -> Result<FileInitial, AppError> {
    let mut file = File::open(path).map_err(|e| {
        AppError::with_source(format!("Could not open file: {:?}", path), e.toString())
    })?;
    let mut bytes = Vec::new();
    file.read_to_end(&mut bytes).map_err(|e| {
        AppError::with_source(format!("Error reading file: {:?}", path), e.toString())
    })?;
    let content_len = bytes.len() as u64;
    let mut complete: Vec<String> = Vec::new();
    let mut start = 0usize;
    for (i, b) in bytes.iter().enumerate() {
        if *b == b'\n' {
            let mut chunk = &bytes[start..i];
            if chunk.ends_with(b"\r") { chunk = &chunk[..chunk.len()-1]; }
            match String::from_utf8(chunk.to_vec()) {
                Ok(s) => complete.push(s),
                Err(_) => return Err(failed_signal_err()),
            }
            start = i + 1;
        }
    }
    let partial = if start < bytes.len() { Some(bytes[start..].to_vec()) } else { None };
    Ok(FileInitial { complete_lines: complete, partial, content_len })
}

fn handle_file(
    path: &Path,
    print_mode: bool,
    pager_kind: Option<Pager>,
    pager_str: Option<&str>,
    follow_for_less: bool,
    highs: &Arc<HighlighterSet>,
) -> Result<(), AppError> {
    let initial = read_file_initial(path)?;

    if print_mode {
        if initial.complete_lines.is_empty() {
            let mut out = stdout_writer();
            let _ = out.write_all(b"\n");
            let _ = out.flush();
            return Ok(());
        }
        let mut out = stdout_writer();
        for line in &initial.complete_lines {
            let _ = writeln!(out, "{}", highs.highlight(line));
        }
        let _ = out.flush();
        return Ok(());
    }

    // Pager mode
    let temp = crate::tempfile::create_temp_output().map_err(|e| AppError::simple(e.toString()))?;
    let temp_path_str = temp.file_path.display().to_string();

    // Build the real pager (with real temp path)
    let pager = build_pager(pager_str, follow_for_less, &temp_path_str)?;
    let _ = pager_kind; // validation only

    // Compute initial lines
    let mut lines: Vec<String> = Vec::new();
    for line in &initial.complete_lines {
        lines.push(highs.highlight(line));
    }
    if initial.complete_lines.is_empty() {
        lines.push(String::new());
    }
    let mut partial_invalid = false;
    if let Some(partial_bytes) = &initial.partial {
        match String::from_utf8(partial_bytes.clone()) {
            Ok(mut s) => {
                if s.ends_with('\r') { s.pop(); }
                lines.push(highs.highlight(&s));
            }
            Err(_) => { partial_invalid = true; }
        }
    }

    // Write to temp
    {
        let mut f = &temp.file;
        for line in &lines {
            let _ = writeln!(f, "{}", line);
        }
        let _ = f.flush();
    }

    // Spawn pager
    let (program, pargs) = crate::pager::command_for(&pager, &temp_path_str);
    let mut child = spawn_pager(&program, &pargs)?;

    if partial_invalid {
        // Wait for pager to finish, then report the IO error
        let status = child.wait().map_err(|e| AppError::simple(e.toString()))?;
        if !status.success() {
            return Err(pager_nonzero(status));
        }
        return Err(could_not_read_next_line("stream did not contain valid UTF-8".to_string()));
    }

    // Follow loop while pager runs
    let mut offset = initial.content_len;
    let mut temp_file = temp.file.try_clone().map_err(|e| AppError::simple(e.toString()))?;
    loop {
        // check pager
        match child.try_wait() {
            Ok(Some(status)) => {
                if status.success() { return Ok(()); }
                return Err(pager_nonzero(status));
            }
            Ok(None) => {}
            Err(e) => return Err(AppError::simple(e.toString())),
        }
        std::thread::sleep(Duration::from_millis(50));
        // poll file
        if let Err(e) = poll_file_once(path, &mut offset, highs, &mut temp_file) {
            // kill pager?
            let _ = child.kill();
            let _ = child.wait();
            return Err(e);
        }
    }
}

fn spawn_pager(program: &str, args: &[String]) -> Result<Child, AppError> {
    Command::new(program)
        .args(args)
        .stdin(Stdio::inherit())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .spawn()
        .map_err(|e| AppError::with_code("less::command_spawn", "Could not run pager", Some(e.toString())))
}

fn pager_nonzero(status: std::process::ExitStatus) -> AppError {
    AppError::with_code(
        "less::non_zero_exit",
        format!("Pager exited with non-zero status: {}", status),
        None,
    )
}

// Returns Err(AppError) if reading next line fails (invalid UTF-8 / IO)
fn poll_file_once(path: &Path, offset: &mut u64, highs: &Arc<HighlighterSet>, dest: &mut dyn Write) -> Result<(), AppError> {
    let meta = match fs::metadata(path) { Ok(m) => m, Err(_) => return Ok(()) };
    if meta.len() <= *offset { return Ok(()); }
    let mut f = match File::open(path) { Ok(f) => f, Err(_) => return Ok(()) };
    if f.seek(SeekFrom::Start(*offset)).is_err() { return Ok(()); }
    let mut buf = Vec::new();
    f.read_to_end(&mut buf).map_err(|e| could_not_read_next_line(e.toString()))?;
    if buf.is_empty() { return Ok(()); }
    *offset += buf.len() as u64;
    // split into lines
    let mut start = 0usize;
    for (i, b) in buf.iter().enumerate() {
        if *b == b'\n' {
            let mut chunk = &buf[start..i];
            if chunk.ends_with(b"\r") { chunk = &chunk[..chunk.len()-1]; }
            let s = String::from_utf8(chunk.to_vec())
                .map_err(|_| could_not_read_next_line("stream did not contain valid UTF-8".to_string()))?;
            writeln!(dest, "{}", highs.highlight(&s)).map_err(|e| AppError::simple(e.toString()))?;
            dest.flush().ok();
            start = i + 1;
        }
    }
    if start < buf.len() {
        let mut chunk = &buf[start..];
        if chunk.ends_with(b"\r") { chunk = &chunk[..chunk.len()-1]; }
        let s = String::from_utf8(chunk.to_vec())
            .map_err(|_| could_not_read_next_line("stream did not contain valid UTF-8".to_string()))?;
        if !s.is_empty() || true {
            writeln!(dest, "{}", highs.highlight(&s)).map_err(|e| AppError::simple(e.toString()))?;
            dest.flush().ok();
        }
    }
    Ok(())
}

// ---------- Exec ----------

fn spawn_shell(cmd: &str) -> io::Result<Child> {
    Command::new("sh")
        .arg("-c")
        .arg(cmd)
        .stdin(Stdio::inherit())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
}

fn handle_exec_print(cmd: &str, highs: &Arc<HighlighterSet>) -> Result<(), AppError> {
    let mut child = spawn_shell(cmd).map_err(|e| AppError::simple(e.toString()))?;
    if let Some(stdout) = child.stdout.take() {
        let mut out = stdout_writer();
        let res = process_pipe(stdout, highs, &mut out);
        let _ = out.flush();
        // do not wait for child (mirrors process exit behaviour); but reap quickly if already done
        let _ = child.try_wait();
        return res;
    }
    Ok(())
}

fn handle_exec_pager(
    cmd: &str,
    _pager_kind: Option<Pager>,
    pager_str: Option<&str>,
    highs: &Arc<HighlighterSet>,
) -> Result<(), AppError> {
    let temp = crate::tempfile::create_temp_output().map_err(|e| AppError::simple(e.toString()))?;
    let temp_path_str = temp.file_path.display().to_string();
    let pager = build_pager(pager_str, true, &temp_path_str)?;

    let mut child_cmd = spawn_shell(cmd).map_err(|e| AppError::simple(e.toString()))?;
    let cmd_stdout = child_cmd.stdout.take();

    // Reader thread writes to temp file clone
    let (tx, rx) = std::sync::mpsc::channel::<Result<(), String>>();
    if let Some(stdout) = cmd_stdout {
        let highs_clone = Arc::clone(highs);
        let mut temp_clone = temp.file.try_clone().map_err(|e| AppError::simple(e.toString()))?;
        std::thread::spawn(move || {
            let mut writer = io::BufWriter::new(&mut temp_clone);
            let res = process_pipe(stdout, &highs_clone, &mut writer);
            let _ = writer.flush();
            let _ = tx.send(res.map_err(|e| e.message.clone()));
        });
    }

    let (program, pargs) = crate::pager::command_for(&pager, &temp_path_str);
    let mut pager_child = spawn_pager(&program, &pargs)?;

    // Wait pager
    let status = pager_child.wait().map_err(|e| AppError::simple(e.toString()))?;
    // Check reader error if already available
    if let Ok(Err(msg)) = rx.try_recv() {
        return Err(AppError::simple(msg));
    }
    if !status.success() {
        return Err(pager_nonzero(status));
    }
    Ok(())
}

// ---------- Stdin / pipe processing ----------

pub fn process_pipe<R: Read>(reader: R, highs: &Arc<HighlighterSet>, out: &mut dyn Write) -> Result<(), AppError> {
    let mut br = BufReader::with_capacity(65536, reader);
    let mut pending: Vec<u8> = Vec::new();
    loop {
        let avail_snapshot: Vec<u8>;
        {
            let avail = br.fill_buf().map_err(|e| AppError::simple(e.toString()))?;
            if avail.is_empty() { break; }
            avail_snapshot = avail.to_vec();
        }
        let consumed = avail_snapshot.len();
        br.consume(consumed);
        let spanning = !pending.is_empty();
        let mut data = pending.clone();
        data.extend_from_slice(&avail_snapshot);
        // find newline positions
        let mut complete: Vec<(usize, usize)> = Vec::new(); // start, end (excl newline)
        let mut line_start = 0usize;
        for (i, b) in data.iter().enumerate() {
            if *b == b'\n' {
                complete.push((line_start, i));
                line_start = i + 1;
            }
        }
        if complete.is_empty() {
            pending = data;
            continue;
        }
        let remainder = data[line_start..].to_vec();
        let total_complete = complete.len();
        for (idx, (s, e)) in complete.iter().enumerate() {
            let line_bytes = &data[*s..*e];
            let strict = if spanning && idx == 0 {
                true
            } else if total_complete == 1 {
                true
            } else {
                false
            };
            let line_str: String = if strict {
                match String::from_utf8(line_bytes.to_vec()) {
                    Ok(s) => s,
                    Err(_) => return Err(AppError::simple("stream did not contain valid UTF-8")),
                }
            } else {
                String::from_utf8_lossy(line_bytes).into_owned()
            };
            writeln!(out, "{}", highs.highlight(&line_str)).map_err(|e| AppError::simple(e.toString()))?;
            out.flush().ok();
        }
        pending = remainder;
    }
    if !pending.is_empty() {
        let line_str = match String::from_utf8(pending.clone()) {
            Ok(s) => s,
            Err(_) => return Err(AppError::simple("stream did not contain valid UTF-8")),
        };
        writeln!(out, "{}", highs.highlight(&line_str)).map_err(|e| AppError::simple(e.toString()))?;
        out.flush().ok();
    }
    Ok(())
}
