//! Minimal terminal size query for Unix terminals (used to satisfy clap's wrap_help).
use std::os::raw::{c_int, c_ulong};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

#[repr(C)]
#[derive(Default)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: c_int, request: c_ulong, arg: *mut WinSize) -> c_int;
}

const TIOCGWINSZ: c_ulong = 0x5413;

fn size_of_fd(fd: c_int) -> Option<(Width, Height)> {
    let mut ws = WinSize::default();
    let rc = unsafe { ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) };
    if rc == 0 && ws.ws_col > 0 {
        Some((Width(ws.ws_col), Height(ws.ws_row)))
    } else {
        None
    }
}

/// Returns the size of the terminal, querying stdout, then stderr, then stdin.
pub fn terminal_size() -> Option<(Width, Height)> {
    size_of_fd(1).or_else(|| size_of_fd(2)).or_else(|| size_of_fd(0))
}
RS
