use crate::segment::{push_plain, Seg, Segs};
use crate::style::Style;

fn is_ascii_word(b: u8) -> bool { b.is_ascii_alphanumeric() || b == b'_' }

pub fn apply(text: &str, style: Style) -> Segs {
    let bytes = text.as_bytes();
    let mut out: Segs = Vec::new();
    let mut last = 0usize;
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i].is_ascii_digit() {
            // attempt greedy match [0-9]+(\.[0-9]+)?
            let mut end = i;
            while end < bytes.len() && bytes[end].is_ascii_digit() { end += 1; }
            if end + 1 < bytes.len() && bytes[end] == b'.' && bytes[end+1].is_ascii_digit() {
                end += 1;
                while end < bytes.len() && bytes[end].is_ascii_digit() { end += 1; }
            }
            let prev_ok = i == 0 || !is_ascii_word(bytes[i-1]);
            let next_ok = end >= bytes.len() || !is_ascii_word(bytes[end]);
            if prev_ok && next_ok {
                push_plain(&mut out, &text[last..i]);
                out.push(Seg::styled(text[i..end].to_string(), style));
                last = end;
                i = end;
                continue;
            }
        }
        i += 1;
    }
    push_plain(&mut out, &text[last..]);
    out
}
