        // Split the line into chunks at ANSI CSI sequences. Text after an escape
        // sequence is considered already styled (and is emitted verbatim), except
        // after the exact reset sequence ESC[0m, where plain highlighting resumes.
        let mut out = String::new();
        let mut plain_state = true;
        let bytes = line.as_bytes();
        let mut i = 0usize;
        while i < line.len() {
            if bytes[i] == 0x1b && i + 1 < line.len() && bytes[i+1] == b'[' {
                // parse CSI: parameter/intermediate bytes 0x20..=0x3F, then a final byte 0x40..=0x7E
                let mut j = i + 2;
                let mut found_final = false;
                while j < line.len() {
                    let b = bytes[j];
                    if (0x40..=0x7e).contains(&b) { found_final = true; break; }
                    if (0x20..=0x3f).contains(&b) { j += 1; continue; }
                    break;
                }
                if found_final {
                    let seq = &line[i..=j];
                    out.push_str(seq);
                    plain_state = seq == "\\x1b[0m";
                    i = j + 1;
                } else {
                    // Unterminated sequence: emit the rest verbatim
                    out.push_str(&line[i..]);
                    break;
                }
            } else {
                // text run up to next CSI start
                let rest = &line[i..];
                let next = rest.find("\\x1b[").map(|p| i + p).unwrap_or(line.len());
                let chunk = &line[i..next];
                if plain_state {
                    out.push_str(&crate::segment::render(&self.highlight_segs(chunk)));
                } else {
                    out.push_str(chunk);
                }
                i = next;
            }
        }
        out
    }"""
