import pathlib

# keywords: single-pass scan with first-char buckets
p=pathlib.Path("src/highlight/keywords.rs"); t=p.read_text()
old_fn_start = t.index("pub fn apply_keyword_group")
t = t[:old_fn_start] + '''pub fn apply_keyword_group(text: &str, group: &KeywordGroup) -> Segs {
    // Bucket words by first byte for a fast single pass
    let mut buckets: std::collections::HashMap<u8, Vec<&String>> = std::collections::HashMap::new();
    for w in &group.words {
        if w.is_empty() { continue; }
        buckets.entry(w.as_bytes()[0]).or_default().push(w);
    }
    for bucket in buckets.values_mut() { bucket.sort(); }
    let bytes = text.as_bytes();
    let mut out: Segs = Vec::new();
    let mut last = 0usize;
    let mut i = 0usize;
    while i < bytes.len() {
        // prev char must not be ASCII word char
        if i > 0 && is_ascii_word_char(text[..i].chars().last().unwrap()) {
            i += text[i..].chars().next().map(|c| c.len_utf8()).unwrap_or(1);
            continue;
        }
        if let Some(cands) = buckets.get(&bytes[i]) {
            let mut matched: Option<usize> = None;
            for w in cands {
                if text[i..].starts_with(w.as_str()) {
                    let e = i + w.len();
                    let next_ok = if e >= text.len() { true } else { !is_ascii_word_char(text[e..].chars().next().unwrap()) };
                    if next_ok { matched = Some(e); break; }
                }
            }
            if let Some(e) = matched {
                crate::segment::push_plain(&mut out, &text[last..i]);
                let matched_text = &text[i..e];
                let display = if group.style.bg.is_some() {
                    format!(" {} ", matched_text)
                } else {
                    matched_text.to_string()
                };
                out.push(Seg::styled(display, group.style));
                last = e;
                i = e;
                continue;
            }
        }
        i += text[i..].chars().next().map(|c| c.len_utf8()).unwrap_or(1);
    }
    crate::segment::push_plain(&mut out, &text[last..]);
    out
}
'''
